}

async function loadDiskCache() {
  // 新路径优先；没有则读旧路径做一次性迁移（冷启动不丢数）
  for (const p of [cacheFilePath(), legacyCacheFilePath()]) {
    if (!p) continue;
    const j = await readJson(p);
    if (j && typeof j === "object" && (j.ok || j.error)) {
