async function atomicWrite(path, text) {
  const tmp = `${path}.tmp`;
  await mkdir(dirname(path), { recursive: true });
  await writeFile(tmp, text, "utf8");
  try {
    await rename(tmp, path);
  } catch {
    // Windows 上目标被占用时 rename 可能失败，退化为直接覆盖
    await writeFile(path, text, "utf8");
  }
}

